parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "categorie": {
      "type": "string",
      "enum": [
        "devis",
        "facture_paiement",
        "sav_reclamation",
        "rendez_vous",
        "prospection_spam",
        "autre"
      ]
    },
    "urgence": {
      "type": "string",
      "enum": [
        "haute",
        "normale",
        "basse"
      ]
    },
    "resume": {
      "type": "string",
      "description": "Résumé en une ou deux phrases"
    },
    "entreprise": {
      "type": "string",
      "description": "Entreprise de l'expéditeur si elle est mentionnée, sinon vide"
    },
    "telephone": {
      "type": "string",
      "description": "Numéro de téléphone s'il figure dans le message, sinon vide"
    },
    "reponse_proposee": {
      "type": "string",
      "description": "Brouillon de réponse au client"
    }
  },
  "required": [
    "categorie",
    "urgence",
    "resume",
    "reponse_proposee"
  ]
}

options.systemPromptTemplate:
Tu es l'assistant administratif d'une TPE du bâtiment (menuiserie). Tu analyses chaque email entrant.
Catégories possibles :
- devis : demande de prix, de chiffrage ou de visite technique ;
- facture_paiement : facture, paiement, avoir, relance d'un fournisseur ;
- sav_reclamation : problème sur un chantier ou un produit posé, réclamation, garantie ;
- rendez_vous : prise, modification ou annulation de rendez-vous ;
- prospection_spam : démarchage commercial, newsletter, publicité, spam ;
- autre : tout le reste.
Urgence « haute » uniquement si un dommage est en cours, si un client est bloqué ou si une échéance tombe sous 48 h.
La réponse proposée est un brouillon poli, en français, signé « L'équipe Chêne & Cie », qui n'invente ni prix ni date.
Réponds uniquement avec les champs demandés.

parameters.jsCode:
// Associe chaque catégorie au bon service et prépare le message transmis.
const services = {
  devis: { service: 'Commercial', to: 'commercial@chene-et-cie.demo' },
  facture_paiement: { service: 'Comptabilité', to: 'compta@chene-et-cie.demo' },
  sav_reclamation: { service: 'SAV', to: 'sav@chene-et-cie.demo' },
  rendez_vous: { service: 'Planning', to: 'planning@chene-et-cie.demo' },
  prospection_spam: { service: 'Archivé', to: '' },
  autre: { service: 'Accueil', to: 'contact@chene-et-cie.demo' },
};
const email = $('Email entrant (simulation)').item.json;
const ia = $json.output;
const cible = services[ia.categorie] ?? services.autre;
const esc = s => String(s ?? '').replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const urgent = ia.urgence === 'haute';
return {
  ...ia,
  ...cible,
  urgent,
  sujet: (urgent ? '[URGENT] ' : '') + '[' + cible.service + '] ' + email.objet,
  html: `<div style="font-family:Arial,sans-serif;max-width:640px">
<p style="background:${urgent ? '#fdecea' : '#eef4f7'};padding:10px 14px;border-radius:6px">
<b>Catégorie :</b> ${esc(ia.categorie)} · <b>Urgence :</b> ${esc(ia.urgence)}<br>
<b>Résumé IA :</b> ${esc(ia.resume)}</p>
<p><b>Expéditeur :</b> ${esc(email.de_nom)} &lt;${esc(email.de_email)}&gt;${ia.entreprise ? ' · ' + esc(ia.entreprise) : ''}${ia.telephone ? ' · ' + esc(ia.telephone) : ''}</p>
<h3 style="margin-bottom:4px">Brouillon de réponse (à relire avant envoi)</h3>
<pre style="white-space:pre-wrap;font-family:inherit;border-left:3px solid #4A5B6B;padding-left:10px">${esc(ia.reponse_proposee)}</pre>
<h3 style="margin-bottom:4px">Message d'origine</h3>
<p><b>Objet :</b> ${esc(email.objet)}</p>
<pre style="white-space:pre-wrap;font-family:inherit;color:#555">${esc(email.message)}</pre></div>`,
};
